/* S-mart Living Storefront — Carrito y Checkout Conceptual V1. Independent, nonproduction review layer. */
.commerce[hidden],.commerce-mobile-action[hidden]{display:none!important}
.commerce{background:linear-gradient(180deg,#f6f9fd 0%,#fff 64%);min-height:525px;padding:24px 28px 32px;color:#102b4a}
