.commerce-item:last-child{border-bottom:0}.commerce-photo{background:#f8fafc;border:1px solid #eef2f7;border-radius:12px;width:90px;height:85px;display:grid;place-items:center;padding:10px;overflow:hidden}
.commerce-photo img{max-width:100%;max-height:100%;object-fit:contain}.commerce-item-info{min-width:0}.commerce-item-brand{font-size:10px;color:#3b759f;font-weight:750;display:block;margin-bottom:5px}
.commerce-item-name{font-size:13px;line-height:1.35;font-weight:800;color:#0e2447;margin-bottom:7px}.commerce-item-price{font-size:14px;color:#08294f;font-weight:820;white-space:nowrap}
.commerce-item-actions{display:flex;flex-direction:column;gap:9px;align-items:flex-end}.commerce-quantity{display:flex;align-items:center;border:1px solid #d7e3ef;border-radius:12px;overflow:hidden;background:#fff}
.commerce-quantity button{display:grid;place-items:center;background:#f7faff;color:#174b84;border:0;min-width:34px;height:34px;font-size:17px;line-height:1}.commerce-quantity button:disabled{opacity:.35;cursor:not-allowed}
.commerce-quantity span{min-width:25px;text-align:center;font-weight:760;font-size:12px}.commerce-remove{font-size:10px;color:#687b90;text-decoration:underline;text-underline-offset:3px;border:0;background:transparent;padding:5px}
.commerce-note{display:flex;gap:9px;align-items:start;padding:13px 16px;background:#f1f8fe;color:#345472;border:1px solid #deeffb;border-radius:14px;margin-top:15px;font-size:11px;line-height:1.5}
.commerce-note .icon{width:17px;height:17px;color:#0872ae;margin-top:1px}.commerce-summary{padding:17px 18px}.commerce-summary h3{font-size:16px;margin:0 0 16px;font-weight:800}
