/* V1.1 — Ajuste conceptual solicitado: zoom discreto al apuntar sobre la tarjeta.
   Limitado al catálogo de escritorio; sin afectar otras pantallas ni estilos aprobados. */
@media (hover: hover) and (pointer: fine) {
  .desk .catalog-product .photo { overflow: hidden; }
  .desk .catalog-product .photo img {
    transform-origin: 50% 50%;
    transition: transform 240ms cubic-bezier(.2,.7,.2,1);
  }
  .desk .catalog-product:hover .photo img,
  .desk .catalog-product:focus-within .photo img { transform: scale(1.055); }
}
@media (prefers-reduced-motion: reduce) {
  .desk .catalog-product .photo img { transition: none !important; transform: none !important; }
}

